    val MAP: Map<String, DuaText> = mapOf(
        "dua_yamani_hajar" to DuaText("Rukn Yamani ve Hacer Esved arasında", "Rabbimiz, bize dünyada da iyilik ver, ahirette de iyilik ver ve bizi ateş azabından koru.", "Tavafta Yemen Köşesi ile Hacer-Taş arasında.", "Peygamber ﷺ bu yerde tavafta bunu okudu."),
        "dua_safa_marwa" to DuaText("Safa ve Merve hakkında", "Tek ve ortağı olmayan Allah'tan başka ibadet edilmeye hak yoktur. Mülk O'nundur, hamd O'nundur ve O, her şeye gücü yetendir. Yalnızca Allah'tan başka ibadet edilmeye hak yoktur; Vaadini yerine getirdi, kuluna yardım etti ve tek başına müttefikleri mağlup etti.", "Safa'ya çıkıp kıbleye yönelmek (üç defa).", "Peygamber ﷺ'nın Safa ve Merve'deki zikri."),
        "dua_arafah" to DuaText("Arefe gününün en güzel duası", "Tek ve ortağı olmayan Allah'tan başka ibadet edilmeye hak yoktur. Mülk O'nundur, hamd O'nundur ve O, her şeye gücü yetendir.", "Arefe Günü - en iyi dua.", "Duanın en hayırlısı Arefe günü yapılan duadır, sözlerin en hayırlısı da budur."),
        "dua_takbeer_tashreeq" to DuaText("Tekbir-e-Taşrik", "Allah en büyüktür, Allah en büyüktür. Allah'tan başka ilah yoktur. Allah en büyüktür, Allah en büyüktür ve hamd Allah'a mahsustur.", "9 Zilhicce sabahından 13 Zilhicce asrına kadar her farz namazdan sonra.", "Ali ve İbn Mes'ud'dan rivayet edilmiştir (RA) - Hanefilere göre vaciptir."),
        "dua_zamzam" to DuaText("Zemzem içmek", "Allah'ım Senden faydalı ilim, bol rızık ve her hastalığa şifa diliyorum.", "Zemzem içerken, niyet ettiğiniz şey için dua edin.", "Zemzem ne için içilirse o içindir (İbn Mâce 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Yaratılışı Düşünmek", "Rabbimiz, bütün bunları boşuna yaratmadın. Sen yücesin, bizi ateşin azabından koru.", "Göklerin ve yerin yaratılışı üzerinde düşünenlerin duası.", "Anlayışlı insanların duası (ulü'l-elbab)."),
        "dua_q_sami_na_munadiyan" to DuaText("İmana Çağıranı İşittik", "Rabbimiz, 'Rabbinize inanın' diye imana çağıran bir davetçiyi işittik ve iman ettik. Rabbimiz, günahlarımızı bağışla, kötülüklerimizi ört ve bizi salihlerle birlikte öldür.", "İman etmek ve salihler arasında ölmek için yapılan bir dua.", "Bağışlanma ve güzel son için bir dua."),
        "dua_q_atina_ma_waadtana" to DuaText("Bize Vaadettiğinizi Verin", "Rabbimiz, peygamberlerin aracılığıyla vaad ettiğin şeyleri bize ver ve kıyamet gününde bizi rezil etme. Şüphesiz sen sözünden dönmezsin.", "Kıyamet gününde rezil olmaktan sığın.", "Ahirette şeref aramak."),
        "dua_q_israfana" to DuaText("Aşırılıklarımızı Bağışlayın", "Rabbimiz, günahlarımızı ve işlerimizdeki taşkınlıklarımızı bağışla, ayaklarımızı sabit kıl ve kâfirler topluluğuna karşı bize yardım et.", "Önceki peygamberlerin sahabelerinin duası.", "Sabır ve bağışlanma için bir dua."),
        "dua_q_jamiun_nas" to DuaText("İnsanlığı Toplayacaksın", "Rabbimiz, şüphesiz sen, geleceğinde şüphe olmayan bir günde insanları toplayacaksın. Şüphesiz Allah vaadinden caymaz.", "Kıyamet gününün kesinliğini tasdik eden.", "Bilgiye sağlam temellenenlerin duası."),
        "dua_q_maash_shahidin" to DuaText("Tanıkların Arasına Yazın", "Rabbimiz, biz iman ettik, öyleyse bizi şahitlerden yaz.", "Gerçeği tanıyıp iman edenlerin duası.", "Kişinin imanının kabulü için yapılan dua."),
        "dua_q_la_tajalna_zalimin" to DuaText("Yanlış yapanlarla değil", "Rabbimiz, bizi zalimler topluluğunun arasına koyma.", "Araf halkının duası.", "Zalimlerin kaderinden sığın."),
        "dua_q_tawaffana_muslimin" to DuaText("Müslümanlar olarak sabır ve ölüm", "Rabbimiz, üzerimize sabır yağdır ve bizi Müslüman olarak öldür.", "Firavun'un sihirbazlarının iman ettikleri zaman yaptıkları dua.", "İmtihanda sabır ve imanla son."),
        "dua_q_la_tajalna_fitnah" to DuaText("Zalimlerin Yargılanması Değil", "Biz Allah'a güveniriz. Rabbimiz, bizi zalimler topluluğu için bir fitne kılma ve rahmetinle bizi kâfir kavimden kurtar.", "Musa kavminin duası (AS).", "Zulüm ve zalimlerden kurtuluş için dua."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Nuh'un Bağışlanma Duası (AS)", "Rabbim, hakkında bilgim olmayan şeyi Senden istemekten Sana sığınırım. Ve eğer beni bağışlamaz ve bana merhamet etmezsen, ben de hüsrana uğrayanlardan olurum.", "Nuh Peygamber'in tövbe duası (AS).", "Uygun görgü kurallarıyla sorma konusunda bir ders."),
        "dua_q_mudkhala_sidq" to DuaText("Gerçeğin Girişi ve Çıkışı", "Rabbim, bana hakla girmeyi ve hakla çıkmayı nasip et ve bana katından destekleyici bir güç ver.", "Yeni bir göreve, eve veya yere girmeden önce.", "Dua Hicret sırasında Peygamber ﷺ'ya öğretildi."),
        "dua_q_la_tadharni_fardan" to DuaText("Zekeriya Duası (AS) — Beni Yalnız Bırakma", "Rabbim beni yalnız bırakma, sen mirasçıların en hayırlısısın.", "Çocuk arayanlar için.", "Bu dua sayesinde Allah Yahya’ya (AS)’yı bağışladı."),
        "dua_q_munzalan_mubarakan" to DuaText("Kutsanmış Bir İniş Yeri", "Rabbim, beni mübarek bir yere indir, Sen karaya çıkaranların en hayırlısısın.", "Yeni bir eve taşınırken veya bir yerde konaklarken Nuh'un duası (AS).", "Yeni bir yerde bereket için dua."),
        "dua_q_amanna_faghfir" to DuaText("Biz İnandık, Bizi Bağışla", "Rabbimiz, biz iman ettik, bizi bağışla, bize merhamet et, Sen merhametlilerin en hayırlısısın.", "Allah'ın salih kullarının duası.", "Bağışlanma ve merhamet için kapsamlı bir dua."),
        "dua_q_isrif_jahannam" to DuaText("Cehennem Azabını Önleyin", "Rabbimiz, Cehennem azabını bizden uzaklaştır; şüphesiz onun cezası süreklidir. Gerçekten o ne kötü bir yerleşme ve yerleşmedir.", "Rahman'ın kullarının duası ('Ibad ar-Rahman).", "Cehennemden korunmak için Kur'an'dan okunan dua."),
        "dua_q_hab_li_hukman" to DuaText("İbrahim'in Duası (AS) — Bilgelik ve Cennet", "Rabbim, bana hikmet ver ve beni salihlerin arasına kat, gelecek nesiller arasında beni anılmayı nasip eyle ve beni Nimetli Cennetin varislerinden eyle.", "Hikmeti, salihlerin arkadaşlığını ve cenneti istemek.", "İbrahim (AS)'nın kapsamlı bir duası."),
        "dua_q_lut_najjini_ahli" to DuaText("Lut'un Duası (AS) — Ailemi Kurtar", "Rabbim, beni ve ailemi onların yaptıklarının şerrinden koru.", "Ailesini kötülük ortamından korumak.", "Ailenin kötülüklerden korunması."),
        "dua_q_sulaiman_awzini" to DuaText("Süleyman'ın Şükran Duası (AS)", "Rabbim, bana ve ana-babama verdiğin nimete şükretmeyi, razı olacağın salih ameller işlemeyi bana nasip et ve rahmetinle beni salih kullarının arasına kat.", "Nimetlere şükretme yeteneğinden dolayı.", "Süleyman (AS)'nın şükran duası."),
        "dua_q_musa_zalamtu" to DuaText("Musa'nın Duası (AS) — Kendime zulmettim", "Rabbim, ben kendime zulmettim, beni bağışla.", "Hatadan hemen sonra pişmanlık.", "Allah Musa'yı (AS) affetti."),
        "dua_q_musa_najjini" to DuaText("Musa'nın Duası (AS) — Beni Zalimlerden Kurtar", "Rabbim, beni zalimler topluluğundan kurtar.", "Zalimlerden korkarken.", "Musa'nın Mısır'dan ayrılırken yaptığı dua (AS)."),
        "dua_q_lut_unsurni" to DuaText("Lut'un Duası (AS) — Yolsuzluk yapanlara karşı yardım", "Rabbim, bozgunculuk yapan kavme karşı bana yardım et.", "Yolsuzluğu yayanlara karşı yardım için.", "Hak üzerinde ısrarla duranların duasıdır."),
        "dua_q_hab_li_salihin" to DuaText("Salih Bir Çocuk İçin İbrahim'in Duası (AS)", "Rabbim bana salihlerden (bir çocuk) bağışla.", "Salih çocuklar istemek.", "Bu dua sayesinde İsmail (AS) bahşedildi."),
        "dua_q_wasita_kulla_shay" to DuaText("Arşı Taşıyan Meleklerin Duası", "Rabbimiz, sen rahmetin ve ilminle her şeyi kuşatmışsın, o halde tövbe edenleri ve senin yoluna uyanları bağışla ve onları cehennem azabından koru.", "Arşı taşıyan melekler müminler için bu duayı yaparlar.", "Meleklerin duasına dahil olmak niyetiyle okunur."),
        "dua_q_ikhwanina" to DuaText("Bizden Önce Gelen Kardeşlerimiz İçin", "Rabbimiz, bizi ve bizden önce iman eden kardeşlerimizi bağışla ve kalplerimizde iman edenlere karşı bir kırgınlık bırakma. Rabbimiz, sen gerçekten çok şefkatli ve merhametlisin.", "Daha önce gelen müminler ve temiz bir kalp için bir dua.", "Asil Sahabeler (RA) ve önceki inananlar için bir dua."),
        "dua_q_alayka_tawakkalna" to DuaText("Sana Güveniyoruz (İbrahim AS)", "Rabbimiz, sana tevekkül ettik, sana yöneldik ve dönüş sanadır. Rabbimiz, bizi inkarcılar için bir fitne kılma ve bizi bağışla. Rabbimiz, sen gerçekten Azizsin, Hakimsin.", "İbrahim (AS) ve ashabının duası.", "Allah'a tevekkül ve O'na yönelme duasıdır."),
        "dua_q_atmim_nurana" to DuaText("Işığımızı Mükemmelleştirin", "Rabbimiz, bizim nurumuzu tamamla ve bizi bağışla. Şüphesiz Sen her şeye kadirsin.", "Mü'minlerin kıyamet günü duası.", "Sırat'ın nurunu diliyorum."),
        "dua_q_asiya_baytan" to DuaText("Asiye Duası — Cennette Bir Ev", "Rabbim, bana katında cennette bir ev yap, beni Firavun'dan ve onun yaptıklarından kurtar ve beni zalimler topluluğundan kurtar.", "Firavun'un karısı Asiya'nın duası.", "Allah onu müminlere örnek kıldı."),
        "dua_adhan_response" to DuaText("Ezan'a yanıt vermek", "Allah'tan başka kuvvet ve kuvvet yoktur.", "Müezzinin söylediklerini tekrarlayın; 'Hayya 'ales-salah' ve 'Hayya 'alel-felah' bunu söylüyor.", "Kim gönülden karşılık verirse Cennete girer."),
        "dua_adhan_shahadah" to DuaText("Müezzinin Şehadetinden Sonra", "Ben de tek ve ortağı olmayan Allah'tan başka ilah olmadığına ve Muhammed ﷺ'nın O'nun kulu ve elçisi olduğuna şahitlik ederim. Rab olarak Allah'tan, Resul olarak Muhammed ﷺ'den ve din olarak İslam'dan razı oldum.", "Müezzinin iman şahitliğini duyunca.", "Günahları bağışlanır."),
        "dua_istiftah_baid" to DuaText("Açılış Duası: Beni Günahlardan Uzaklaştır", "Allah'ım, doğuyu batıdan uzaklaştırdığın gibi beni de günahlarımdan uzaklaştır. Allah'ım, beyaz elbisenin kirden temizlendiği gibi beni de günahlardan arındır. Allah'ım günahlarımı su, kar ve dolu ile yıka.", "Açılış tekbirinden sonra (Sana yerine de söylenebilir).", "Peygamber ﷺ bunu tekbir ile okuma arasında okudu."),
        "dua_hamdan_kathiran" to DuaText("Rükudan Sonra Bol Hamd", "Rabbimiz, hamd sana mahsustur; bol, pak ve mübarek hamd.", "Rükudan kalktıktan sonra \"Rabbena lekel-hamd\" ile birlikte.", "Otuzdan fazla melek bunu ilk kaydeden kişi olmak için yarışıyordu."),
        "dua_subbuhun_quddus" to DuaText("Subbühun Kuddüs (Rüku ve Secde)", "(Allah) çok yücedir, çok kutsaldır, meleklerin ve Ruh'un (Cebrail) Rabbidir.", "Rüku ve secdede.", "Peygamber ﷺ bunu rüku ve secdede okudu."),
        "dua_sujood_dhanbi_kullah" to DuaText("Secdede: Bütün Günahlarımı Bağışla", "Allah'ım, günahlarımın küçüğünü, büyüğünü, ilkini ve sonunu, açığını ve gizlisini bağışla.", "Secdede.", "Secde duaların kabul edildiği yerdir."),
        "dua_sujood_ridaka" to DuaText("Zevkinize Sığının", "Allah'ım, gazabından rızana, azabından affına, şerrinden sana sığınırım. Seni tam olarak övemem; Kendini övdüğün gibisin.", "Secdede — Aişe (RA) Peygamber'in ﷺ bunu söylediğini duydu.", "Peygamberimizin secde duası ﷺ."),
        "dua_tashahhud" to DuaText("Teşehhüd (Tahiyyat)", "Sözlü, fiziki ve mali her türlü ibadet Allah içindir. Selam sana ey Peygamber, Allah'ın rahmeti ve bereketi sana olsun. Selam bize ve Allah'ın salih kullarının üzerine olsun. Şehadet ederim ki Allah'tan başka ilah yoktur ve Muhammed ﷺ'nın O'nun kulu ve Resulü olduğuna şahitlik ederim.", "Her oturuşta - Abdullah ibn Mes'ud (RA) (Hanefi uygulaması) tarafından anlatılmıştır.", "Peygamber ﷺ bunu Kur'an'ın bir suresi gibi öğretmiştir."),
